ng // publisher address (lowercase)\n  canonical       String // canonical JSON string\n  hash            String   @unique\n  uri             String\n  repoId          String?\n  parentId        String?\n  chainRef        String? // on-chain ID string\n  transactionHash String?\n  published       Boolean  @default(false)\n  chainAddress    String   @default(\"\")\n  createdAt       DateTime @default(now())\n\n  @@index([kind, published])\n}\n\nmodel VerifiedSubmission {\n  id              String   @id @default(cuid())\n  opportunityId   String\n  wallet          String\n  githubId        String\n  repoId          String\n  prNumber        Int\n  reference       String\n  url             String\n  title           String\n  login           String\n  notes           String\n  prState         String // \"open\" | \"closed\" | \"merged\"\n  commit          String\n  syncedAt        DateTime\n  nextSyncAt      DateTime\n  syncError       String?\n  transactionHash String?\n  chainRef        String?\n  chainAddress    String   @default(\"\")\n  createdAt       DateTime @default(now())\n\n  @@index([repoId, prNumber])\n  @@index([opportunityId, wallet])\n}\n\nmodel ChainEvent {\n  id              String @id @default(cuid())\n  chainId         Int\n  transactionHash String\n  logIndex        Int\n  blockNumber     String\n  eventName       String\n  payload         String\n  contractAddress String @default(\"\")\n\n  @@unique([chainId, transactionHash, logIndex])\n}\n\nmodel Checkpoint {\n  id    String @id\n  block String\n}\n\nmodel Transaction {\n  hash            String   @id\n  wallet          String\n  status          String\n  blockNumber     String?\n  contractAddress String   @default(\"\")\n  updatedAt       DateTime @updatedAt\n}\n\nmodel WebhookDelivery {\n  id         String   @id\n  status     String\n  receivedAt DateTime @default(now())\n}\n\nmodel Project {\n  id                  String   @id @default(cuid())\n  onChainId           Int?     @unique\n  publisherAddress    String\n  name                String\n  shortDescription    String\n  detailedDescription String\n  category            String\n  technologies        String // JSON array string\n  repoId              String // Canonical \"owner/repo\"\n  repoUrl             String\n  liveDappUrl         String\n  demoVideoUrl        String?\n  metadataURI         String?\n  metadataHash        String?\n  txHash              String?\n  createdAt           DateTime @default(now())\n  updatedAt           DateTime @updatedAt\n\n  opportunities Opportunity[]\n}\n\nmodel Opportunity {\n  id                   String   @id @default(cuid())\n  onChainId            Int?     @unique\n  projectId            String\n  project              Project  @relation(fields: [projectId], references: [id], onDelete: Cascade)\n  publisherAddress     String\n  title                String\n  taskType             String // bug | feature | documentation | optimization | security\n  description          String\n  acceptanceCriteria   String\n  difficulty           String // Beginner | Intermediate | Advanced\n  requiredSkills       String // JSON array string\n  rewardEth            String // Display string (e.g. \"0.5\")\n  rewardWei            String // Exact integer wei string (e.g. \"500000000000000000\")\n  deadline             DateTime\n  issueUrl             String?\n  metadataURI          String?\n  metadataHash         String?\n  state                String   @default(\"OPEN\") // OPEN | APPROVED | PAID | REFUNDED\n  selectedSubmissionId String?\n  txHash               String?\n  createdAt            DateTime @default(now())\n  updatedAt            DateTime @updatedAt\n\n  submissions Submission[]\n}\n\nmodel Submission {\n  id                 String      @id @default(cuid())\n  onChainId          Int?        @unique\n  opportunityId      String\n  opportunity        Opportunity @relation(fields: [opportunityId], references: [id], onDelete: Cascade)\n  contributorAddress String\n  githubUsername     String?\n  githubUserId       String?\n  prUrl              String\n  prNumber           Int\n  repoOwner          String\n  repoName           String\n  notes              String?\n  status             String      @default(\"PENDING\") // PENDING | APPROVED | REJECTED | PAID\n  isMerged           Boolean     @default(false)\n  mergedAt           DateTime?\n  latestCommitSha    String?\n  isRewardReady      Boolean     @default(false)\n  txHash             String?\n  paidTxHash         String?\n  createdAt          DateTime    @default(now())\n  updatedAt          DateTime    @updatedAt\n}\n",
